raw.css:
:root {
  --color-primary: #1e5a96;
  --color-primary-dark: #0d3d6b;
  --color-primary-light: #e8f1f7;
  --color-accent: #d97706;
  --color-accent-dark: #92460f;
  --color-accent-light: #fef3c7;
  --color-text: #1f2937;
  --color-text-light: #6b7280;
  --color-bg: #ffffff;
  --color-bg-alt: #f9fafb;
  --color-border: #e5e7eb;
  --color-success: #059669;
  --font-sans: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, "Helvetica Neue", Arial, sans-serif;
  --font-serif: Georgia, "Times New Roman", serif;
  --spacing-xs: 0.5rem;
  --spacing-sm: 1rem;
  --spacing-md: 1.5rem;
  --spacing-lg: 2rem;
  --spacing-xl: 3rem;
  --spacing-2xl: 4rem;
  --radius: 0.375rem;
}

* {
  margin: 0;
  padding: 0;
  box-sizing: border-box;
}

html {
  scroll-behavior: smooth;
}

body {
  font-family: var(--font-sans);
  font-size: 1rem;
  line-height: 1.6;
  color: var(--color-text);
  background-color: var(--color-bg);
}

.container {
  max-width: 1200px;
  margin: 0 auto;
  padding: 0 var(--spacing-md);
}

/* Typography */
h1, h2, h3, h4, h5, h6 {
  font-family: var(--font-serif);
  font-weight: 700;
  line-height: 1.3;
  color: var(--color-primary-dark);
}

h1 {
  font-size: clamp(1.875rem, 5vw, 3rem);
  margin-bottom: var(--spacing-md);
}

h2 {
  font-size: clamp(1.5rem, 4vw, 2.25rem);
  margin-bottom: var(--spacing-md);
}

h3 {
  font-size: 1.25rem;
  margin-bottom: var(--spacing-sm);
}

p {
  margin-bottom: var(--spacing-md);
  color: var(--color-text);
}

a {
  color: var(--color-primary-dark);
  text-decoration: none;
  transition: color 0.2s ease;
}

a:hover {
  color: var(--color-accent);
}

a:focus-visible {
  outline: 2px solid var(--color-accent);
  outline-offset: 2px;
  border-radius: var(--radius);
}

/* Header */
.header {
  background-color: var(--color-bg);
  border-bottom: 1px solid var(--color-border);
  padding: var(--spacing-md) 0;
  position: sticky;
  top: 0;
  z-index: 100;
}

.header .container {
  display: flex;
  align-items: center;
  justify-content: space-between;
}

.logo {
  font-family: "Courier New", monospace;
  font-size: clamp(1.25rem, 4vw, 1.75rem);
  font-weight: 700;
  letter-spacing: 0.05em;
  color: var(--color-primary-dark);
  display: inline-flex;
  align-items: center;
  gap: 0.25rem;
  transition: color 0.2s ease;
}

.logo:hover {
  color: var(--color-accent);
}

.logo:focus-visible {
  outline: 2px solid var(--color-accent);
  outline-offset: 4px;
}

.logo span {
  color: var(--color-accent);
  font-size: 1.2em;
}

/* Footer */
.footer {
  background-color: var(--color-bg-alt);
  border-top: 1px solid var(--color-border);
  padding: var(--spacing-2xl) 0;
  margin-top: var(--spacing-2xl);
}

.footer .container {
  text-align: center;
}

.footer p {
  font-size: 0.95rem;
  color: var(--color-text-light);
  margin-bottom: var(--spacing-sm);
}

.footer a {
  color: var(--color-primary-dark);
}

/* Buttons */
button,
.btn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  min-height: 44px;
  padding: var(--spacing-sm) var(--spacing-lg);
  font-size: 1rem;
  font-weight: 600;
  font-family: var(--font-sans);
  border: none;
  border-radius: var(--radius);
  cursor: pointer;
  text-decoration: none;
  transition: all 0.2s ease;
}

.btn-primary {
  background-color: var(--color-primary-dark);
  color: var(--color-bg);
}

.btn-primary:hover {
  background-color: var(--color-primary);
  transform: translateY(-2px);
  box-shadow: 0 4px 12px rgba(13, 61, 107, 0.2);
}

.btn-primary:focus-visible {
  outline: 2px solid var(--color-accent);
  outline-offset: 2px;
}

.btn-secondary {
  background-color: transparent;
  color: var(--color-primary-dark);
  border: 2px solid var(--color-primary-dark);
}

.btn-secondary:hover {
  background-color: var(--color-primary-light);
}

.btn-secondary:focus-visible {
  outline: 2px solid var(--color-accent);
  outline-offset: 2px;
}

/* Forms */
label {
  display: block;
  margin-bottom: var(--spacing-xs);
  font-weight: 600;
  color: var(--color-text);
}

input,
textarea,
select {
  width: 100%;
  padding: 0.75rem;
  font-family: var(--font-sans);
  font-size: 1rem;
  border: 1px solid var(--color-border);
  border-radius: var(--radius);
  transition: border-color 0.2s ease, box-shadow 0.2s ease;
}

input:focus,
textarea:focus,
select:focus {
  outline: none;
  border-color: var(--color-primary);
  box-shadow: 0 0 0 3px rgba(30, 90, 150, 0.1);
}

textarea {
  resize: vertical;
  min-height: 120px;
}

.form-group {
  margin-bottom: var(--spacing-md);
}

/* Cards */
.card {
  background-color: var(--color-bg);
  border: 1px solid var(--color-border);
  border-radius: var(--radius);
  padding: var(--spacing-lg);
  transition: all 0.3s ease;
}

.card:hover {
  box-shadow: 0 8px 24px rgba(13, 61, 107, 0.12);
  transform: translateY(-4px);
  border-color: var(--color-accent);
}

/* Grid */
.grid {
  display: grid;
  gap: var(--spacing-lg);
}

.grid-2 {
  grid-template-columns: 1fr;
}

.grid-3 {
  grid-template-columns: 1fr;
}

/* Sections */
section {
  padding: var(--spacing-2xl) 0;
}

section:nth-child(even) {
  background-color: var(--color-bg-alt);
}

.section-title {
  text-align: center;
  margin-bottom: var(--spacing-2xl);
}

.section-title h2 {
  color: var(--color-primary-dark);
  margin-bottom: var(--spacing-sm);
}

.section-title p {
  font-size: 1.1rem;
  color: var(--color-text-light);
  max-width: 600px;
  margin: 0 auto;
}

/* Pricing Badge */
.price {
  font-size: 2rem;
  font-weight: 700;
  color: var(--color-accent-dark);
  margin: var(--spacing-md) 0;
}

.price-period {
  font-size: 0.9rem;
  color: var(--color-text-light);
  font-weight: 400;
}

/* Responsive Design */
@media (max-width: 600px) {
  .container {
    padding: 0 var(--spacing-sm);
  }

  .header .container {
    flex-direction: column;
    gap: var(--spacing-sm);
  }

  section {
    padding: var(--spacing-xl) 0;
  }

  .section-title {
    margin-bottom: var(--spacing-xl);
  }

  .grid-2,
  .grid-3 {
    grid-template-columns: 1fr;
  }

  h1 {
    font-size: 1.75rem;
  }

  h2 {
    font-size: 1.35rem;
  }

  button,
  .btn {
    width: 100%;
  }
}

@media (min-width: 601px) {
  .grid-2 {
    grid-template-columns: repeat(2, 1fr);
  }

  .grid-3 {
    grid-template-columns: repeat(3, 1fr);
  }
}

@media (prefers-reduced-motion: reduce) {
  * {
    animation-duration: 0.01ms !important;
    animation-iteration-count: 1 !important;
    transition-duration: 0.01ms !important;
    scroll-behavior: auto !important;
  }
}

